-- =============================================================================
-- S.A.R.A - Script Completo de Creación y Población de Base de Datos (Room v4)
-- Motor: SQLite 3 (Android Room 2.6.1, PRAGMA user_version = 4)
-- Contenido:
--   * 50 Pacientes (adultos mayores chilenos)
--   * 50 Familiares / Contactos de emergencia (1 por paciente)
--   * 10 Recordatorios clínicos y cotidianos
--   * 5 Juegos de estimulación cognitiva
--   * 125 Sesiones en historial_estimulacion (2-3 por paciente, 25 por juego)
-- =============================================================================

PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

-- -----------------------------------------------------------------------------
-- 1. ESTRUCTURA DE TABLAS E ÍNDICES (ESQUEMA ROOM v4)
-- -----------------------------------------------------------------------------
CREATE TABLE `Paciente` (`Id_paciente` INTEGER NOT NULL, `Nombre` TEXT NOT NULL, `ape_p` TEXT NOT NULL, `ape_m` TEXT NOT NULL, `Fech_nac` TEXT NOT NULL, `edad` INTEGER NOT NULL, `genero` TEXT NOT NULL, `estado` INTEGER NOT NULL, PRIMARY KEY(`Id_paciente`));
CREATE TABLE `recordatorios` (`id_recordatorio` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `descripcion` TEXT NOT NULL, `fecha_recor` TEXT NOT NULL, `Paciente_Id_paciente` INTEGER NOT NULL, FOREIGN KEY(`Paciente_Id_paciente`) REFERENCES `Paciente`(`Id_paciente`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `Contacto_emergencia` (`id_contacto` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `nombre` TEXT NOT NULL, `apellido` TEXT NOT NULL, `numero_tel` INTEGER NOT NULL, `Paciente_Id_paciente` INTEGER NOT NULL, `estado` INTEGER NOT NULL, FOREIGN KEY(`Paciente_Id_paciente`) REFERENCES `Paciente`(`Id_paciente`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `juegos` (`id_juego` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `descripcion` TEXT NOT NULL);
CREATE TABLE `historial_estimulacion` (`id_historial` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `fecha_rea` TEXT NOT NULL, `puntuacion` INTEGER NOT NULL, `observaciones` TEXT NOT NULL, `Paciente_Id_paciente` INTEGER NOT NULL, `juegos_id_juego2` INTEGER NOT NULL, FOREIGN KEY(`Paciente_Id_paciente`) REFERENCES `Paciente`(`Id_paciente`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`juegos_id_juego2`) REFERENCES `juegos`(`id_juego`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `chat` (`id_chat` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `emisor` TEXT NOT NULL, `mensaje` TEXT NOT NULL, `fecha_hora` INTEGER NOT NULL, `leido` INTEGER NOT NULL, `Paciente_id_paciente` INTEGER NOT NULL, `Contacto_emergencia_id_contacto` INTEGER NOT NULL, FOREIGN KEY(`Paciente_id_paciente`) REFERENCES `Paciente`(`Id_paciente`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`Contacto_emergencia_id_contacto`) REFERENCES `Contacto_emergencia`(`id_contacto`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `biometria_paciente` (`id_biometria` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `id_paciente` INTEGER NOT NULL, `vector_biometrico` TEXT NOT NULL, `consentimiento_otorgado` INTEGER NOT NULL, `fecha_registro` INTEGER NOT NULL, FOREIGN KEY(`id_paciente`) REFERENCES `Paciente`(`Id_paciente`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
CREATE INDEX `index_recordatorios_Paciente_Id_paciente` ON `recordatorios` (`Paciente_Id_paciente`);
CREATE INDEX `index_Contacto_emergencia_Paciente_Id_paciente` ON `Contacto_emergencia` (`Paciente_Id_paciente`);
CREATE INDEX `index_historial_estimulacion_Paciente_Id_paciente` ON `historial_estimulacion` (`Paciente_Id_paciente`);
CREATE INDEX `index_historial_estimulacion_juegos_id_juego2` ON `historial_estimulacion` (`juegos_id_juego2`);
CREATE INDEX `index_chat_Paciente_id_paciente` ON `chat` (`Paciente_id_paciente`);
CREATE INDEX `index_chat_Contacto_emergencia_id_contacto` ON `chat` (`Contacto_emergencia_id_contacto`);
CREATE UNIQUE INDEX `index_biometria_paciente_id_paciente` ON `biometria_paciente` (`id_paciente`);

-- Metadatos de control de versión de Android Room
INSERT OR REPLACE INTO room_master_table (id, identity_hash) VALUES (42, 'c156ccccc4ec2172821d7fb19d0ba657');

