-- 5. POBLACIÓN DE JUEGOS DE ESTIMULACIÓN COGNITIVA (5 REGISTROS)
-- -----------------------------------------------------------------------------
INSERT OR REPLACE INTO `juegos` (`id_juego`, `descripcion`) VALUES (1, 'Trivia de Época (Música, Cine e Historia): Preguntas de los años 60, 70 u 80 con 3 opciones. Mide memoria remota y semántica. Parámetros: % aciertos y tiempo de respuesta.');
INSERT OR REPLACE INTO `juegos` (`id_juego`, `descripcion`) VALUES (2, '¿Quién soy? (Adivinanza por Pistas): Hasta 3 pistas progresivas sobre un personaje, lugar u objeto. Mide razonamiento deductivo y léxico. Parámetros: pistas usadas (3/2/1 pts) y fallos.');
INSERT OR REPLACE INTO `juegos` (`id_juego`, `descripcion`) VALUES (3, 'Mito o Realidad (Verdadero / Falso): Afirmaciones de cultura general y dichos populares para respuesta rápida. Mide velocidad de procesamiento y juicio lógico. Parámetros: aciertos, racha y latencia.');
INSERT OR REPLACE INTO `juegos` (`id_juego`, `descripcion`) VALUES (4, 'Termina la Canción: SARA recita el inicio de un coro clásico y el paciente completa la frase. Mide memoria auditiva, lenguaje y atención sostenida. Parámetros: frases completadas, ayudas y fluidez.');
INSERT OR REPLACE INTO `juegos` (`id_juego`, `descripcion`) VALUES (5, '¿Qué Pasó Primero?: Compara dos hitos históricos famosos para elegir cuál ocurrió antes. Mide orientación temporal y función ejecutiva. Parámetros: aciertos sobre rondas y tiempo de deliberación.');

